import 'package:flutter/material.dart';import '../models/user.dart';import '../services/api.dart';import 'admin_login.dart';import 'admin.dart';
class AdminHome extends StatefulWidget{final User user;const AdminHome({super.key,required this.user});@override State<AdminHome> createState()=>_AdminHomeState();}
class _AdminHomeState extends State<AdminHome>{int i=0;Future<void>logout()async{await Api.logout();if(!mounted)return;Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const AdminLogin()),(_)=>false);} @override Widget build(BuildContext c)=>Scaffold(backgroundColor:const Color(0xFFF4F4F8),appBar:AppBar(backgroundColor:const Color(0xFF151525),foregroundColor:Colors.white,title:Text(i==0?'Control center':['Users','Communities','Posts','Messages','App update'][i-1]),actions:[IconButton(onPressed:logout,icon:const Icon(Icons.logout))]),drawer:Drawer(child:ListView(padding:EdgeInsets.zero,children:[Container(height:180,color:const Color(0xFF151525),padding:const EdgeInsets.all(22),alignment:Alignment.bottomLeft,child:const Text('CAMPUSMATE\nADMIN',style:TextStyle(color:Colors.white,fontSize:24,fontWeight:FontWeight.w900,letterSpacing:1))),_item(0,Icons.dashboard,'Overview'),_item(1,Icons.people,'Users'),_item(2,Icons.groups,'Communities'),_item(3,Icons.article,'Posts'),_item(4,Icons.forum,'Messages'),_item(5,Icons.system_update,'App update')])) ,body:Admin(user:widget.user,section:i));}Widget _item(int x,IconData icon,String label)=>ListTile(leading:Icon(icon),title:Text(label),selected:i==x,onTap:(){setState(()=>i=x);Navigator.pop(context);});}
